<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Users</title></head><body><h1>Users</h1><a href="/dashboard">Dashboard</a><table border="1" cellpadding="8"><tr><th>ID</th><th>Name</th><th>Email</th><th>Role</th></tr><?php foreach($users as $u): ?><tr><td><?=e($u['id'])?></td><td><?=e($u['name'])?></td><td><?=e($u['email'])?></td><td><?=e($u['role'])?></td></tr><?php endforeach; ?></table><h2>Create User</h2><form method="post"><input type="hidden" name="_token" value="<?=e(csrf_token())?>"><input name="name" placeholder="Name" required><input name="email" type="email" placeholder="Email" required><input name="password" type="password" placeholder="Password" required><button>Create</button></form></body></html>
